create database hozitech_db
    with owner dev;

grant connect on database hozitech_db to chatbot_read_only;

CREATE TABLE public.addresses (
    id uuid NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    created_by character varying(255),
    updated_at timestamp(6) without time zone,
    updated_by character varying(255),
    detail_address character varying(255) NOT NULL,
    district character varying(100) NOT NULL,
    full_name character varying(100) NOT NULL,
    is_default boolean NOT NULL,
    phone_number character varying(15) NOT NULL,
    province character varying(100) NOT NULL,
    ward character varying(100) NOT NULL,
    user_id uuid NOT NULL
);


ALTER TABLE public.addresses OWNER TO dev;

