    discount_value numeric(15,2),
    end_date timestamp(6) without time zone,
    max_discount_amount numeric(15,2),
    min_order_value numeric(15,2),
    start_date timestamp(6) without time zone,
    status character varying(50) NOT NULL,
    usage_limit integer,
    used_count integer NOT NULL,
    is_public boolean DEFAULT false NOT NULL,
    apply_type character varying(30) DEFAULT 'ALL'::character varying NOT NULL,
    coupon_category character varying(30) DEFAULT 'PRODUCT'::character varying,
    CONSTRAINT coupons_usage_limit_check CHECK ((usage_limit >= 0)),
    CONSTRAINT coupons_used_count_check CHECK ((used_count >= 0))
);


ALTER TABLE public.coupons OWNER TO dev;

