    updated_by character varying(255),
    description character varying(255),
    status character varying(20) NOT NULL,
    order_id uuid NOT NULL,
    CONSTRAINT order_status_history_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'CONFIRMED'::character varying, 'PROCESSING'::character varying, 'SHIPPING'::character varying, 'SHIPPED'::character varying, 'CANCELLED'::character varying, 'RETURNED'::character varying])::text[])))
