--
-- Name: orders; Type: TABLE; Schema: public; Owner: dev
--

CREATE TABLE public.orders (
    id uuid NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    created_by character varying(255),
    updated_at timestamp(6) without time zone,
    updated_by character varying(255),
    coupon_code character varying(50),
    discount_amount numeric(15,2) NOT NULL,
    note character varying(500),
    order_number character varying(30) NOT NULL,
    order_status character varying(20) NOT NULL,
    payment_method character varying(20) NOT NULL,
    payment_status character varying(20) NOT NULL,
    shipping_address_json jsonb,
    shipping_fee numeric(15,2) NOT NULL,
    subtotal numeric(15,2) NOT NULL,
    total_amount numeric(15,2) NOT NULL,
    user_id uuid NOT NULL,
    tracking_code character varying(50),
    shipping_coupon_code character varying(50),
    shipping_discount_amount numeric(15,2) DEFAULT 0.00,
    tax_amount numeric(15,2) DEFAULT 0.00,
    tax_mode character varying(20),
    tax_percent numeric(5,2) DEFAULT 0.00,
    taxable_amount numeric(15,2) DEFAULT 0.00,
    tax_apply_on_shipping boolean DEFAULT false NOT NULL,
    idempotency_key character varying(120),
    CONSTRAINT orders_order_status_check CHECK (((order_status)::text = ANY ((ARRAY['PENDING'::character varying, 'CONFIRMED'::character varying, 'PROCESSING'::character varying, 'SHIPPING'::character varying, 'SHIPPED'::character varying, 'CANCELLED'::character varying, 'RETURNED'::character varying])::text[]))),
    CONSTRAINT orders_payment_method_check CHECK (((payment_method)::text = ANY ((ARRAY['COD'::character varying, 'VNPAY'::character varying, 'MOMO'::character varying, 'BANK_TRANSFER'::character varying])::text[]))),
    CONSTRAINT orders_payment_status_check CHECK (((payment_status)::text = ANY ((ARRAY['PENDING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying])::text[]))),
    CONSTRAINT orders_tax_mode_check CHECK (((tax_mode)::text = ANY ((ARRAY['INCLUDED'::character varying, 'EXCLUDED'::character varying])::text[])))
);


ALTER TABLE public.orders OWNER TO dev;

