--
-- Name: v_chatbot_product_variants; Type: VIEW; Schema: public; Owner: dev
--

CREATE VIEW public.v_chatbot_product_variants AS
 WITH attribute_summary AS (
         SELECT pvav.product_variant_id,
            string_agg(concat(va.name, ': ', vao.label), ' | '::text ORDER BY COALESCE(cva.sort_order, 0), COALESCE(vao.sort_order, 0), va.name, vao.label) AS attribute_summary
           FROM (((((public.product_variant_attribute_values pvav
             JOIN public.product_variants pv_1 ON ((pv_1.id = pvav.product_variant_id)))
             JOIN public.products p_1 ON ((p_1.id = pv_1.product_id)))
             JOIN public.variant_attributes va ON ((va.id = pvav.variant_attribute_id)))
             JOIN public.variant_attribute_options vao ON ((vao.id = pvav.option_id)))
             LEFT JOIN public.category_variant_attributes cva ON (((cva.category_id = p_1.category_id) AND (cva.variant_attribute_id = pvav.variant_attribute_id))))
          GROUP BY pvav.product_variant_id
        )
 SELECT pv.id,
    pv.product_id,
    p.name AS product_name,
    p.slug AS product_slug,
    p.category_id,
    c.name AS category_name,
    p.brand_id,
    b.name AS brand_name,
    pv.sku,
    pv.display_name,
    pv.variant_signature,
    pv.price,
    pv.compare_at_price,
    pv.stock_quantity,
    pv.status,
    pv.created_at,
    attr.attribute_summary
   FROM ((((public.product_variants pv
     JOIN public.products p ON ((p.id = pv.product_id)))
     LEFT JOIN public.categories c ON ((c.id = p.category_id)))
     LEFT JOIN public.brands b ON ((b.id = p.brand_id)))
     LEFT JOIN attribute_summary attr ON ((attr.product_variant_id = pv.id)));


ALTER VIEW public.v_chatbot_product_variants OWNER TO dev;

--
-- Name: v_chatbot_flash_sale_items; Type: VIEW; Schema: public; Owner: dev
--

CREATE VIEW public.v_chatbot_flash_sale_items AS
 SELECT f.id AS flash_sale_id,
    f.name AS sale_name,
    f.status AS sale_status,
    f.start_time,
    f.end_time,
    fi.variant_id,
    cv.product_id,
    cv.product_name,
    cv.product_slug,
    cv.category_name,
    cv.brand_name,
    cv.display_name,
    cv.attribute_summary,
    fi.flash_price,
    fi.flash_stock,
    fi.sold_count
   FROM ((public.flash_sales f
     JOIN public.flash_sale_items fi ON ((fi.flash_sale_id = f.id)))
     JOIN public.v_chatbot_product_variants cv ON ((cv.id = fi.variant_id)));


ALTER VIEW public.v_chatbot_flash_sale_items OWNER TO dev;

--
-- Name: v_chatbot_products; Type: VIEW; Schema: public; Owner: dev
--

CREATE VIEW public.v_chatbot_products AS
 WITH variant_stats AS (
         SELECT pv.product_id,
            min(pv.price) FILTER (WHERE (COALESCE(pv.status, true) = true)) AS min_price,
            max(pv.price) FILTER (WHERE (COALESCE(pv.status, true) = true)) AS max_price,
            (COALESCE(sum(pv.stock_quantity) FILTER (WHERE (COALESCE(pv.status, true) = true)), (0)::bigint))::integer AS total_stock
           FROM public.product_variants pv
          GROUP BY pv.product_id
        ), feedback_stats AS (
         SELECT f.product_id,
            round(avg(f.rating), 1) AS avg_rating,
            (count(*))::integer AS review_count
           FROM public.feedbacks f
          WHERE ((f.status)::text = 'APPROVED'::text)
          GROUP BY f.product_id
        ), spec_summary AS (
         SELECT psv.product_id,
            string_agg(concat(sa.name, ': ', psv.value_text), '
'::text ORDER BY COALESCE(csa.sort_order, sa.sort_order, 0), sa.name) AS spec_summary
           FROM (((public.product_spec_values psv
             JOIN public.products p_1 ON ((p_1.id = psv.product_id)))
             JOIN public.spec_attributes sa ON ((sa.id = psv.spec_attribute_id)))
             LEFT JOIN public.category_spec_attributes csa ON (((csa.category_id = p_1.category_id) AND (csa.spec_attribute_id = psv.spec_attribute_id))))
          GROUP BY psv.product_id
        ), main_images AS (
         SELECT DISTINCT ON (pi.product_id) pi.product_id,
            pi.image_url AS main_image_url
           FROM public.product_images pi
          WHERE (pi.variant_id IS NULL)
          ORDER BY pi.product_id, pi.is_primary DESC, pi.sort_order, pi.created_at
        )
 SELECT p.id,
    p.name,
    p.slug,
    p.description,
    p.origin_price,
    p.status,
    p.is_featured,
    p.category_id,
    c.name AS category_name,
    p.brand_id,
    b.name AS brand_name,
    p.created_at,
    vs.min_price,
    vs.max_price,
    COALESCE(vs.total_stock, 0) AS total_stock,
    fs.avg_rating,
    COALESCE(fs.review_count, 0) AS review_count,
    mi.main_image_url,
    ss.spec_summary
   FROM ((((((public.products p
     LEFT JOIN public.categories c ON ((c.id = p.category_id)))
     LEFT JOIN public.brands b ON ((b.id = p.brand_id)))
     LEFT JOIN variant_stats vs ON ((vs.product_id = p.id)))
     LEFT JOIN feedback_stats fs ON ((fs.product_id = p.id)))
     LEFT JOIN spec_summary ss ON ((ss.product_id = p.id)))
     LEFT JOIN main_images mi ON ((mi.product_id = p.id)));


ALTER VIEW public.v_chatbot_products OWNER TO dev;

--
-- Name: v_chatbot_user_purchase_events; Type: VIEW; Schema: public; Owner: dev
--

CREATE VIEW public.v_chatbot_user_purchase_events AS
 SELECT o.user_id,
    o.id AS order_id,
    o.order_status,
    o.created_at AS ordered_at,
    oi.variant_id,
    pv.product_id,
    p.category_id,
    c.name AS category_name,
    p.brand_id,
    b.name AS brand_name,
    oi.unit_price,
    oi.quantity,
    oi.subtotal,
    p.name AS product_name,
    pv.display_name,
    p.status AS product_status,
    pv.status AS variant_status
   FROM (((((public.orders o
     JOIN public.order_items oi ON ((oi.order_id = o.id)))
     JOIN public.product_variants pv ON ((pv.id = oi.variant_id)))
     JOIN public.products p ON ((p.id = pv.product_id)))
     LEFT JOIN public.categories c ON ((c.id = p.category_id)))
     LEFT JOIN public.brands b ON ((b.id = p.brand_id)));


ALTER VIEW public.v_chatbot_user_purchase_events OWNER TO dev;

--
-- Name: v_feedback_stats; Type: VIEW; Schema: public; Owner: hoinguyen
--

CREATE VIEW public.v_feedback_stats AS
 SELECT product_id,
    round(avg(rating), 1) AS avg_rating,
    count(*) AS review_count,
    max(created_at) AS last_review_at
   FROM public.feedbacks
  WHERE ((status)::text = 'APPROVED'::text)
  GROUP BY product_id;


ALTER VIEW public.v_feedback_stats OWNER TO hoinguyen;

--
-- Name: v_product_summary; Type: VIEW; Schema: public; Owner: hoinguyen
--

CREATE VIEW public.v_product_summary AS
 SELECT product_id,
    min(price) AS min_price,
    max(price) AS max_price,
    COALESCE(sum(stock_quantity), (0)::bigint) AS total_stock
   FROM public.product_variants
  WHERE (status = true)
  GROUP BY product_id;


ALTER VIEW public.v_product_summary OWNER TO hoinguyen;

